// prompt-meter code node. Generated from infra/blocks/workflows/lib/nodes/rollup-plan-run.js by build.js.
// Edit the lib files and re-run `node infra/blocks/workflows/build.js`; do not edit this string.
// ---- helper: lib/workflow-io.js
// Reading node outputs, webhook requests and IAM responses inside code nodes.
//
// TODO(spike): the exact data paths are not documented. The workflow skill's examples
// read webhook bodies as `$node[<trigger name>].json.output.<field>`, if-node conditions as
// `$json.output.<field>`, and code nodes read upstream httpRequest results as
// `$json.<field>`. These helpers accept every one of those shapes so the scripts keep
// working whichever one the engine uses; once the spike pins it down they can be narrowed.
//
// Shared helper: function declarations only. Inlined into code nodes by build.js.

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

// Removes one `output` wrapper if present.
function unwrapOutput(value) {
  if (isPlainObject(value) && isPlainObject(value.output)) return value.output;
  return value;
}

// Output of a named upstream node, unwrapped.
function nodeOutput(nodes, name) {
  const entry = nodes && nodes[name];
  if (!entry) return {};
  const json = entry.json !== undefined ? entry.json : entry;
  return unwrapOutput(json) || {};
}

// Items from a dataAction getData / rawQuery result, whatever the wrapper.
function extractItems(result) {
  let value = unwrapOutput(result);
  for (let depth = 0; depth < 6 && value != null; depth++) {
    if (Array.isArray(value)) return value;
    if (!isPlainObject(value)) return [];
    if (Array.isArray(value.items)) return value.items;
    if (value.data !== undefined) { value = value.data; continue; }
    if (value.output !== undefined) { value = value.output; continue; }
    // { getUsageEvents: { items: [...] } } -> the single key's value
    const keys = Object.keys(value).filter(function (k) { return k !== "errors" && k !== "extensions"; });
    if (keys.length === 1 && (isPlainObject(value[keys[0]]) || Array.isArray(value[keys[0]]))) {
      value = value[keys[0]];
      continue;
    }
    return [];
  }
  return [];
}

function extractTotalCount(result) {
  let value = unwrapOutput(result);
  for (let depth = 0; depth < 6 && isPlainObject(value); depth++) {
    if (typeof value.totalCount === "number") return value.totalCount;
    const next = value.data !== undefined ? value.data : value.output !== undefined ? value.output : null;
    if (next !== null) { value = next; continue; }
    const keys = Object.keys(value);
    if (keys.length === 1) { value = value[keys[0]]; continue; }
    return null;
  }
  return null;
}

// True when a GraphQL / dataAction result reports an error.
function resultErrors(result) {
  const value = unwrapOutput(result);
  const errors = [];
  const visit = function (v, depth) {
    if (!isPlainObject(v) || depth > 4) return;
    if (Array.isArray(v.errors) && v.errors.length) errors.push.apply(errors, v.errors);
    if (v.isSuccess === false) errors.push(v.message || v.errors || "isSuccess=false");
    if (v.acknowledged === false) errors.push(v.message || "acknowledged=false");
    const keys = Object.keys(v);
    for (let i = 0; i < keys.length; i++) {
      if (keys[i] !== "errors") visit(v[keys[i]], depth + 1);
    }
  };
  visit(value, 0);
  return errors;
}

function headerValue(headers, name) {
  if (!isPlainObject(headers)) return null;
  const wanted = name.toLowerCase();
  const keys = Object.keys(headers);
  for (let i = 0; i < keys.length; i++) {
    if (keys[i].toLowerCase() === wanted) {
      const v = headers[keys[i]];
      if (Array.isArray(v)) return v.length ? String(v[0]) : null;
      return v === null || v === undefined ? null : String(v);
    }
  }
  return null;
}

function utf8Length(text) {
  let n = 0;
  const s = String(text);
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 0x80) n += 1;
    else if (c < 0x800) n += 2;
    else if (c >= 0xd800 && c <= 0xdbff) { n += 4; i++; }
    else n += 3;
  }
  return n;
}

// Finds headers and body in a webhook trigger's output.
// Returns { headers, body (object|null), rawBody (string|null), parseError (bool) }.
function readWebhookRequest(trigger) {
  const t = isPlainObject(trigger) ? trigger : {};
  const out = isPlainObject(t.output) ? t.output : {};
  const headerCandidates = [t.headers, out.headers, t.request && t.request.headers, out.request && out.request.headers];
  let headers = {};
  for (let i = 0; i < headerCandidates.length; i++) {
    if (isPlainObject(headerCandidates[i])) { headers = headerCandidates[i]; break; }
  }
  const bodyCandidates = [t.body, out.body, t.request && t.request.body, out.request && out.request.body, t.output, t];
  let rawBody = null;
  for (let i = 0; i < bodyCandidates.length; i++) {
    const c = bodyCandidates[i];
    if (isPlainObject(c) && (c.events !== undefined || c.collector !== undefined || c.action !== undefined || c.teamId !== undefined || c.keyId !== undefined || c.mode !== undefined)) {
      return { headers: headers, body: c, rawBody: null, parseError: false };
    }
    if (typeof c === "string" && rawBody === null) rawBody = c;
  }
  if (rawBody !== null) {
    try {
      const parsed = JSON.parse(rawBody);
      return { headers: headers, body: isPlainObject(parsed) ? parsed : null, rawBody: rawBody, parseError: !isPlainObject(parsed) };
    } catch (error) {
      return { headers: headers, body: null, rawBody: rawBody, parseError: true };
    }
  }
  const fallback = isPlainObject(out) && Object.keys(out).length ? out : null;
  return { headers: headers, body: fallback, rawBody: null, parseError: false };
}

// Request size in bytes: Content-Length if sent, else the raw body, else re-serialized JSON.
// TODO(spike): the re-serialized size is only an approximation of the bytes on the wire.
function requestBytes(request) {
  const declared = Number(headerValue(request.headers, "content-length"));
  if (isFinite(declared) && declared > 0) return declared;
  if (typeof request.rawBody === "string") return utf8Length(request.rawBody);
  if (request.body) return utf8Length(JSON.stringify(request.body));
  return 0;
}

// Fixed one-minute window per key. Returns { allowed, retryAfterSeconds, windowStart, windowCount }.
function rateLimitDecision(windowStartIso, windowCount, nowMs, limitPerMinute) {
  const start = windowStartIso ? new Date(windowStartIso).getTime() : NaN;
  const count = typeof windowCount === "number" && windowCount > 0 ? windowCount : 0;
  if (!isNaN(start) && nowMs - start < 60000 && nowMs >= start) {
    if (count >= limitPerMinute) {
      return { allowed: false, retryAfterSeconds: Math.max(1, Math.ceil((start + 60000 - nowMs) / 1000)), windowStart: new Date(start).toISOString(), windowCount: count };
    }
    return { allowed: true, retryAfterSeconds: 0, windowStart: new Date(start).toISOString(), windowCount: count + 1 };
  }
  return { allowed: true, retryAfterSeconds: 0, windowStart: new Date(nowMs).toISOString(), windowCount: 1 };
}

// ---- IAM response readers. TODO(spike): response shapes of /iam/v4/iam/me,
// /iam/v4/iam/organizations/my and /iam/v4/iam/users/{id}?organizationId=... are not
// documented; these accept the common shapes and fail closed (no id / not a member).

function iamPayload(response) {
  let v = unwrapOutput(response);
  for (let i = 0; i < 3 && isPlainObject(v) && v.data !== undefined && !v.itemId && !v.userId; i++) v = v.data;
  return v;
}

function extractUserId(meResponse) {
  const v = iamPayload(meResponse);
  if (!isPlainObject(v)) return null;
  const candidates = [v.itemId, v.ItemId, v.userId, v.id, v.user && (v.user.itemId || v.user.id)];
  for (let i = 0; i < candidates.length; i++) {
    if (typeof candidates[i] === "string" && candidates[i]) return candidates[i];
  }
  return null;
}

function orgIdOf(entry) {
  if (typeof entry === "string") return entry;
  if (!isPlainObject(entry)) return null;
  const c = [entry.organizationId, entry.OrganizationId, entry.itemId, entry.ItemId, entry.id];
  for (let i = 0; i < c.length; i++) if (typeof c[i] === "string" && c[i]) return c[i];
  return null;
}

function rolesOf(entry) {
  if (!isPlainObject(entry)) return [];
  const raw = entry.roles || entry.Roles || entry.roleSlugs || [];
  return (Array.isArray(raw) ? raw : []).map(function (r) {
    return typeof r === "string" ? r : isPlainObject(r) ? r.slug || r.name || "" : "";
  }).filter(Boolean);
}

// Organization memberships as [{ organizationId, roles[] }].
function extractMemberships(response) {
  const v = iamPayload(response);
  const lists = [];
  if (Array.isArray(v)) lists.push(v);
  if (isPlainObject(v)) {
    ["items", "organizations", "memberships", "organizationRoles", "userOrganizations"].forEach(function (k) {
      if (Array.isArray(v[k])) lists.push(v[k]);
    });
  }
  const out = [];
  for (let i = 0; i < lists.length; i++) {
    for (let j = 0; j < lists[i].length; j++) {
      const id = orgIdOf(lists[i][j]);
      if (id) out.push({ organizationId: id, roles: rolesOf(lists[i][j]) });
    }
  }
  // A user record fetched with ?organizationId= may carry a single organizationId + roles.
  if (isPlainObject(v) && typeof v.organizationId === "string" && v.organizationId) {
    out.push({ organizationId: v.organizationId, roles: rolesOf(v) });
  }
  return out;
}

function membershipIn(response, orgId) {
  if (!orgId) return null;
  const list = extractMemberships(response);
  for (let i = 0; i < list.length; i++) if (list[i].organizationId === orgId) return list[i];
  return null;
}

function hasRole(membershipOrResponse, role) {
  const roles = membershipOrResponse && Array.isArray(membershipOrResponse.roles)
    ? membershipOrResponse.roles
    : rolesOf(iamPayload(membershipOrResponse));
  return roles.indexOf(role) >= 0;
}

function hourStartOf(iso) {
  const d = new Date(iso);
  d.setUTCMinutes(0, 0, 0);
  return d.toISOString();
}
// ---- helper: lib/graphql.js
// Builds the raw GraphQL documents that dataAction nodes run (rawQueryMode).
// Naming follows the blocks-data-gateway-crud skill: queries are get<querySchema>
// (naive "s" plural), mutations stay singular (insertX / updateX / deleteX) with bulk
// variants insertManyX / updateManyX / deleteManyX.
//
// TODO(spike): confirm against the live gateway (blocks data schema get <id>):
//   - the querySchema names below (naive plural, e.g. UserHourlys),
//   - the `where` filter operators (eq / in / gte / lt / or),
//   - the argument shape of insertMany* (input: [..]) and update*/delete* (filter: String),
//   - the format of the `filter` string (assumed: Mongo-style JSON) and how DateTime
//     values must be written inside it.
// Every one of these is isolated in this file so the spike only has to fix it here.
//
// Shared helper: function declarations only. Inlined into code nodes by build.js.

const QUERY_NAMES = {
  UsageEvent: "UsageEvents",
  UserHourly: "UserHourlys",
  TeamHourly: "TeamHourlys",
  IngestKey: "IngestKeys",
  ModelPrice: "ModelPrices",
  RollupState: "RollupStates"
};
const MAX_PAGE_SIZE = 10000;

function gqlValue(value) {
  if (value === null || value === undefined) return "null";
  if (typeof value === "number") {
    if (!isFinite(value)) throw new Error("gql_non_finite_number");
    return String(value);
  }
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "string") return JSON.stringify(value);
  if (Array.isArray(value)) return "[" + value.map(gqlValue).join(", ") + "]";
  // Objects are written as "{ a: 1 }" with inner spaces, so a document never contains
  // "{{" or "}}" (the workflow expression delimiters).
  if (typeof value === "object") {
    const keys = Object.keys(value);
    const parts = [];
    for (let i = 0; i < keys.length; i++) {
      if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(keys[i])) throw new Error("gql_bad_field_name");
      parts.push(keys[i] + ": " + gqlValue(value[keys[i]]));
    }
    return parts.length ? "{ " + parts.join(", ") + " }" : "{ }";
  }
  throw new Error("gql_unsupported_value");
}

function gqlFieldList(fields) {
  for (let i = 0; i < fields.length; i++) {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(fields[i])) throw new Error("gql_bad_field_name");
  }
  return fields.join(" ");
}

// query { getX(input: {pageNo: 1, pageSize: n}, where: {...}) { items { ... } totalCount } }
function buildListQuery(schemaName, where, fields, pageSize) {
  const queryName = "get" + QUERY_NAMES[schemaName];
  const size = Math.min(pageSize || MAX_PAGE_SIZE, MAX_PAGE_SIZE);
  return (
    "query { " + queryName + "(input: { pageNo: 1, pageSize: " + size + " }" +
    (where ? ", where: " + gqlValue(where) : "") +
    ") { items { " + gqlFieldList(fields) + " } totalCount } }"
  );
}

// Mongo-style JSON filter string used by update*/delete* mutations. TODO(spike): format.
function filterString(filter) {
  return JSON.stringify(filter);
}

function itemIdFilter(itemId) {
  // TODO(spike): the gateway may expect {"_id": ...} or {"ItemId": ...}.
  return filterString({ _id: itemId });
}

function insertManyField(alias, schemaName, rows) {
  return alias + ": insertMany" + schemaName + "(input: " + gqlValue(rows) + ") { acknowledged totalImpactedData message }";
}

function insertField(alias, schemaName, row) {
  return alias + ": insert" + schemaName + "(input: " + gqlValue(row) + ") { acknowledged itemId message }";
}

function updateField(alias, schemaName, filter, input) {
  return alias + ": update" + schemaName + "(filter: " + gqlValue(filter) + ", input: " + gqlValue(input) + ") { acknowledged totalImpactedData message }";
}

function updateManyField(alias, schemaName, filter, input) {
  return alias + ": updateMany" + schemaName + "(filter: " + gqlValue(filter) + ", input: " + gqlValue(input) + ") { acknowledged totalImpactedData message }";
}

function deleteManyField(alias, schemaName, filter) {
  // TODO(spike): delete* takes `input: XDeleteInput!` per the CRUD skill; its fields are unknown,
  // so only the filter is sent here.
  return alias + ": deleteMany" + schemaName + "(filter: " + gqlValue(filter) + ") { acknowledged totalImpactedData message }";
}

function deleteField(alias, schemaName, filter) {
  return alias + ": delete" + schemaName + "(filter: " + gqlValue(filter) + ") { acknowledged totalImpactedData message }";
}

// Top-level mutation fields run one after another (GraphQL spec), so ordering inside one
// document is safe: e.g. delete the old hourly rows, then insert the rebuilt ones.
function buildMutation(fields) {
  return "mutation { " + fields.join(" ") + " }";
}
// ---- helper: lib/rollup.js
// Hourly rollup planning and aggregation (PLAN.md "Ingest design" -> Rollup).
//  - Watermark: events with receivedAt >= previous run start - 2 minutes.
//  - Never scan further back than 48 hours by receivedAt.
//  - Hours to rebuild = UTC hours (by occurredAt) of those events + RollupState.dirtyHours.
//  - Each rebuilt hour is recomputed from scratch from UsageEvent, so rebuilding twice is harmless.
// Depends on: workflow-io.js (hourStartOf)
//
// Shared helper: function declarations only. Inlined into code nodes by build.js.

const ROLLUP_STATE_NAME = "hourly";
const WATERMARK_OVERLAP_MS = 2 * 60 * 1000;
const SCAN_WINDOW_MS = 48 * 60 * 60 * 1000;
const SUM_FIELDS = [
  "totalInputTokens",
  "uncachedInputTokens",
  "cacheReadTokens",
  "cacheWrite5mTokens",
  "cacheWrite1hTokens",
  "outputTokens",
  "thinkingTokens",
  "serverToolRequests"
];

function normalizeHours(list) {
  const seen = {};
  const out = [];
  const items = Array.isArray(list) ? list : [];
  for (let i = 0; i < items.length; i++) {
    const t = new Date(items[i]).getTime();
    if (isNaN(t)) continue;
    const h = hourStartOf(items[i]);
    if (!seen[h]) { seen[h] = true; out.push(h); }
  }
  return out.sort();
}

function planRollupRun(state, nowMs) {
  const floor = nowMs - SCAN_WINDOW_MS;
  const last = state && state.lastRunStartedAt ? new Date(state.lastRunStartedAt).getTime() : NaN;
  const since = isNaN(last) ? floor : Math.max(last - WATERMARK_OVERLAP_MS, floor);
  return {
    runStartedAt: new Date(nowMs).toISOString(),
    receivedSince: new Date(since).toISOString(),
    dirtyHours: normalizeHours(state && state.dirtyHours)
  };
}

function hoursToRebuild(touchedEvents, dirtyHours) {
  const list = [];
  const events = Array.isArray(touchedEvents) ? touchedEvents : [];
  for (let i = 0; i < events.length; i++) if (events[i] && events[i].occurredAt) list.push(events[i].occurredAt);
  return normalizeHours(list.concat(dirtyHours || []));
}

// `where` filter selecting every event whose occurredAt falls inside one of `hours`.
function hoursWhere(hours) {
  const ranges = hours.map(function (h) {
    const start = new Date(h).getTime();
    return { occurredAt: { gte: new Date(start).toISOString(), lt: new Date(start + 3600000).toISOString() } };
  });
  return ranges.length === 1 ? ranges[0] : { or: ranges };
}

function num(value) {
  return typeof value === "number" && isFinite(value) ? value : 0;
}

function round8(value) {
  return Math.round(value * 1e8) / 1e8;
}

// Builds UserHourly and TeamHourly rows for the given events.
function aggregateHourly(events) {
  const users = {};
  const teams = {};
  const list = Array.isArray(events) ? events : [];
  for (let i = 0; i < list.length; i++) {
    const e = list[i];
    if (!e || !e.userId || !e.teamId || !e.occurredAt) continue;
    const hourStart = hourStartOf(e.occurredAt);
    const tool = e.tool || "other";
    const model = e.model || "unknown";
    const source = e.source || "proxy";
    const uKey = [e.userId, e.teamId, hourStart, tool, model, source].join("|");
    const tKey = [e.teamId, hourStart, tool, model, source].join("|");
    if (!users[uKey]) {
      users[uKey] = { userId: e.userId, teamId: e.teamId, hourStart: hourStart, tool: tool, model: model, source: source, costUsd: 0, eventCount: 0, promptCount: 0, _prompts: {} };
      SUM_FIELDS.forEach(function (f) { users[uKey][f] = 0; });
    }
    if (!teams[tKey]) {
      teams[tKey] = { teamId: e.teamId, hourStart: hourStart, tool: tool, model: model, source: source, costUsd: 0, eventCount: 0 };
      SUM_FIELDS.forEach(function (f) { teams[tKey][f] = 0; });
    }
    const u = users[uKey];
    const t = teams[tKey];
    SUM_FIELDS.forEach(function (f) { u[f] += num(e[f]); t[f] += num(e[f]); });
    u.costUsd += num(e.costUsd);
    t.costUsd += num(e.costUsd);
    u.eventCount += 1;
    t.eventCount += 1;
    const promptKey = e.promptId || e.eventId;
    if (promptKey && !u._prompts[promptKey]) { u._prompts[promptKey] = true; u.promptCount += 1; }
  }
  const sortKey = function (r) { return [r.hourStart, r.teamId, r.userId || "", r.tool, r.model, r.source].join("|"); };
  const userRows = Object.keys(users).map(function (k) {
    const r = users[k];
    delete r._prompts;
    r.costUsd = round8(r.costUsd);
    return r;
  }).sort(function (a, b) { return sortKey(a) < sortKey(b) ? -1 : 1; });
  const teamRows = Object.keys(teams).map(function (k) {
    teams[k].costUsd = round8(teams[k].costUsd);
    return teams[k];
  }).sort(function (a, b) { return sortKey(a) < sortKey(b) ? -1 : 1; });
  return { userRows: userRows, teamRows: teamRows };
}

// Dirty hours still pending after this run: hours marked since the run started stay.
function remainingDirtyHours(latestDirty, processedHours) {
  const done = {};
  (processedHours || []).forEach(function (h) { done[h] = true; });
  return normalizeHours(latestDirty).filter(function (h) { return !done[h]; });
}
// ---- node: lib/nodes/rollup-plan-run.js
// Code node "Plan Rollup Run" (rollup.json). Mode: each. Input: "Load Rollup State".
// Watermark = previous run start - 2 minutes, never more than 48 hours back.
// Helpers: workflow-io, graphql, rollup.

const states = extractItems($json);
const state = states.length ? states[0] : null;
const plan = planRollupRun(state, Date.now());
return Object.assign({}, plan, {
  stateExists: !!state,
  touchedQuery: buildListQuery("UsageEvent", { receivedAt: { gte: plan.receivedSince } }, ["occurredAt"], MAX_PAGE_SIZE)
});

// prompt-meter code node. Generated from infra/blocks/workflows/lib/nodes/rollup-plan-hours.js by build.js.
// Edit the lib files and re-run `node infra/blocks/workflows/build.js`; do not edit this string.
// ---- helper: lib/workflow-io.js
// Reading node outputs, webhook requests and IAM responses inside code nodes.
//
// TODO(spike): the exact data paths are not documented. The workflow skill's examples
// read webhook bodies as `$node[<trigger name>].json.output.<field>`, if-node conditions as
// `$json.output.<field>`, and code nodes read upstream httpRequest results as
// `$json.<field>`. These helpers accept every one of those shapes so the scripts keep
// working whichever one the engine uses; once the spike pins it down they can be narrowed.
//
// Shared helper: function declarations only. Inlined into code nodes by build.js.

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

// Removes one `output` wrapper if present.
function unwrapOutput(value) {
  if (isPlainObject(value) && isPlainObject(value.output)) return value.output;
  return value;
}

// Output of a named upstream node, unwrapped.
function nodeOutput(nodes, name) {
  const entry = nodes && nodes[name];
  if (!entry) return {};
  const json = entry.json !== undefined ? entry.json : entry;
  return unwrapOutput(json) || {};
}

// Items from a dataAction getData / rawQuery result, whatever the wrapper.
function extractItems(result) {
  let value = unwrapOutput(result);
  for (let depth = 0; depth < 6 && value != null; depth++) {
    if (Array.isArray(value)) return value;
    if (!isPlainObject(value)) return [];
    if (Array.isArray(value.items)) return value.items;
    if (value.data !== undefined) { value = value.data; continue; }
    if (value.output !== undefined) { value = value.output; continue; }
    // { getUsageEvents: { items: [...] } } -> the single key's value
    const keys = Object.keys(value).filter(function (k) { return k !== "errors" && k !== "extensions"; });
    if (keys.length === 1 && (isPlainObject(value[keys[0]]) || Array.isArray(value[keys[0]]))) {
      value = value[keys[0]];
      continue;
    }
    return [];
  }
  return [];
}

function extractTotalCount(result) {
  let value = unwrapOutput(result);
  for (let depth = 0; depth < 6 && isPlainObject(value); depth++) {
    if (typeof value.totalCount === "number") return value.totalCount;
    const next = value.data !== undefined ? value.data : value.output !== undefined ? value.output : null;
    if (next !== null) { value = next; continue; }
    const keys = Object.keys(value);
    if (keys.length === 1) { value = value[keys[0]]; continue; }
    return null;
  }
  return null;
}

// True when a GraphQL / dataAction result reports an error.
function resultErrors(result) {
  const value = unwrapOutput(result);
  const errors = [];
  const visit = function (v, depth) {
    if (!isPlainObject(v) || depth > 4) return;
    if (Array.isArray(v.errors) && v.errors.length) errors.push.apply(errors, v.errors);
    if (v.isSuccess === false) errors.push(v.message || v.errors || "isSuccess=false");
    if (v.acknowledged === false) errors.push(v.message || "acknowledged=false");
    const keys = Object.keys(v);
    for (let i = 0; i < keys.length; i++) {
      if (keys[i] !== "errors") visit(v[keys[i]], depth + 1);
    }
  };
  visit(value, 0);
  return errors;
