//   - the `where` filter operators (eq / in / gte / lt / or),
//   - the argument shape of insertMany* (input: [..]) and update*/delete* (filter: String),
//   - the format of the `filter` string (assumed: Mongo-style JSON) and how DateTime
//     values must be written inside it.
// Every one of these is isolated in this file so the spike only has to fix it here.
//
// Shared helper: function declarations only. Inlined into code nodes by build.js.

const QUERY_NAMES = {
  UsageEvent: "UsageEvents",
  UserHourly: "UserHourlys",
  TeamHourly: "TeamHourlys",
  IngestKey: "IngestKeys",
  ModelPrice: "ModelPrices",
  RollupState: "RollupStates"
};
const MAX_PAGE_SIZE = 10000;

function gqlValue(value) {
  if (value === null || value === undefined) return "null";
  if (typeof value === "number") {
    if (!isFinite(value)) throw new Error("gql_non_finite_number");
    return String(value);
  }
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "string") return JSON.stringify(value);
  if (Array.isArray(value)) return "[" + value.map(gqlValue).join(", ") + "]";
  // Objects are written as "{ a: 1 }" with inner spaces, so a document never contains
  // "{{" or "}}" (the workflow expression delimiters).
  if (typeof value === "object") {
    const keys = Object.keys(value);
    const parts = [];
    for (let i = 0; i < keys.length; i++) {
      if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(keys[i])) throw new Error("gql_bad_field_name");
      parts.push(keys[i] + ": " + gqlValue(value[keys[i]]));
    }
    return parts.length ? "{ " + parts.join(", ") + " }" : "{ }";
  }
  throw new Error("gql_unsupported_value");
}

function gqlFieldList(fields) {
  for (let i = 0; i < fields.length; i++) {
    if (!/^[A-Za-z_][A-Za-z0-9_]*$/.test(fields[i])) throw new Error("gql_bad_field_name");
  }
  return fields.join(" ");
}

// query { getX(input: {pageNo: 1, pageSize: n}, where: {...}) { items { ... } totalCount } }
function buildListQuery(schemaName, where, fields, pageSize) {
  const queryName = "get" + QUERY_NAMES[schemaName];
  const size = Math.min(pageSize || MAX_PAGE_SIZE, MAX_PAGE_SIZE);
  return (
    "query { " + queryName + "(input: { pageNo: 1, pageSize: " + size + " }" +
    (where ? ", where: " + gqlValue(where) : "") +
    ") { items { " + gqlFieldList(fields) + " } totalCount } }"
  );
}

// Mongo-style JSON filter string used by update*/delete* mutations. TODO(spike): format.
function filterString(filter) {
  return JSON.stringify(filter);
}

function itemIdFilter(itemId) {
  // TODO(spike): the gateway may expect {"_id": ...} or {"ItemId": ...}.
  return filterString({ _id: itemId });
}

function insertManyField(alias, schemaName, rows) {
  return alias + ": insertMany" + schemaName + "(input: " + gqlValue(rows) + ") { acknowledged totalImpactedData message }";
}

function insertField(alias, schemaName, row) {
  return alias + ": insert" + schemaName + "(input: " + gqlValue(row) + ") { acknowledged itemId message }";
}

function updateField(alias, schemaName, filter, input) {
  return alias + ": update" + schemaName + "(filter: " + gqlValue(filter) + ", input: " + gqlValue(input) + ") { acknowledged totalImpactedData message }";
}

function updateManyField(alias, schemaName, filter, input) {
  return alias + ": updateMany" + schemaName + "(filter: " + gqlValue(filter) + ", input: " + gqlValue(input) + ") { acknowledged totalImpactedData message }";
}

function deleteManyField(alias, schemaName, filter) {
  // TODO(spike): delete* takes `input: XDeleteInput!` per the CRUD skill; its fields are unknown,
  // so only the filter is sent here.
  return alias + ": deleteMany" + schemaName + "(filter: " + gqlValue(filter) + ") { acknowledged totalImpactedData message }";
}

function deleteField(alias, schemaName, filter) {
  return alias + ": delete" + schemaName + "(filter: " + gqlValue(filter) + ") { acknowledged totalImpactedData message }";
}

// Top-level mutation fields run one after another (GraphQL spec), so ordering inside one
// document is safe: e.g. delete the old hourly rows, then insert the rebuilt ones.
function buildMutation(fields) {
  return "mutation { " + fields.join(" ") + " }";
}
// ---- helper: lib/rollup.js
// Hourly rollup planning and aggregation (PLAN.md "Ingest design" -> Rollup).
//  - Watermark: events with receivedAt >= previous run start - 2 minutes.
//  - Never scan further back than 48 hours by receivedAt.
//  - Hours to rebuild = UTC hours (by occurredAt) of those events + RollupState.dirtyHours.
//  - Each rebuilt hour is recomputed from scratch from UsageEvent, so rebuilding twice is harmless.
// Depends on: workflow-io.js (hourStartOf)
//
// Shared helper: function declarations only. Inlined into code nodes by build.js.

const ROLLUP_STATE_NAME = "hourly";
const WATERMARK_OVERLAP_MS = 2 * 60 * 1000;
const SCAN_WINDOW_MS = 48 * 60 * 60 * 1000;
const SUM_FIELDS = [
  "totalInputTokens",
  "uncachedInputTokens",
  "cacheReadTokens",
  "cacheWrite5mTokens",
  "cacheWrite1hTokens",
  "outputTokens",
  "thinkingTokens",
  "serverToolRequests"
];

function normalizeHours(list) {
  const seen = {};
  const out = [];
  const items = Array.isArray(list) ? list : [];
  for (let i = 0; i < items.length; i++) {
    const t = new Date(items[i]).getTime();
    if (isNaN(t)) continue;
    const h = hourStartOf(items[i]);
    if (!seen[h]) { seen[h] = true; out.push(h); }
  }
  return out.sort();
}

function planRollupRun(state, nowMs) {
  const floor = nowMs - SCAN_WINDOW_MS;
  const last = state && state.lastRunStartedAt ? new Date(state.lastRunStartedAt).getTime() : NaN;
  const since = isNaN(last) ? floor : Math.max(last - WATERMARK_OVERLAP_MS, floor);
  return {
    runStartedAt: new Date(nowMs).toISOString(),
    receivedSince: new Date(since).toISOString(),
    dirtyHours: normalizeHours(state && state.dirtyHours)
  };
}

function hoursToRebuild(touchedEvents, dirtyHours) {
  const list = [];
  const events = Array.isArray(touchedEvents) ? touchedEvents : [];
  for (let i = 0; i < events.length; i++) if (events[i] && events[i].occurredAt) list.push(events[i].occurredAt);
  return normalizeHours(list.concat(dirtyHours || []));
}

// `where` filter selecting every event whose occurredAt falls inside one of `hours`.
function hoursWhere(hours) {
  const ranges = hours.map(function (h) {
    const start = new Date(h).getTime();
    return { occurredAt: { gte: new Date(start).toISOString(), lt: new Date(start + 3600000).toISOString() } };
  });
  return ranges.length === 1 ? ranges[0] : { or: ranges };
}

function num(value) {
  return typeof value === "number" && isFinite(value) ? value : 0;
}

function round8(value) {
  return Math.round(value * 1e8) / 1e8;
}

// Builds UserHourly and TeamHourly rows for the given events.
function aggregateHourly(events) {
  const users = {};
  const teams = {};
  const list = Array.isArray(events) ? events : [];
  for (let i = 0; i < list.length; i++) {
    const e = list[i];
    if (!e || !e.userId || !e.teamId || !e.occurredAt) continue;
    const hourStart = hourStartOf(e.occurredAt);
    const tool = e.tool || "other";
    const model = e.model || "unknown";
    const source = e.source || "proxy";
    const uKey = [e.userId, e.teamId, hourStart, tool, model, source].join("|");
    const tKey = [e.teamId, hourStart, tool, model, source].join("|");
    if (!users[uKey]) {
      users[uKey] = { userId: e.userId, teamId: e.teamId, hourStart: hourStart, tool: tool, model: model, source: source, costUsd: 0, eventCount: 0, promptCount: 0, _prompts: {} };
      SUM_FIELDS.forEach(function (f) { users[uKey][f] = 0; });
    }
    if (!teams[tKey]) {
      teams[tKey] = { teamId: e.teamId, hourStart: hourStart, tool: tool, model: model, source: source, costUsd: 0, eventCount: 0 };
      SUM_FIELDS.forEach(function (f) { teams[tKey][f] = 0; });
    }
    const u = users[uKey];
    const t = teams[tKey];
    SUM_FIELDS.forEach(function (f) { u[f] += num(e[f]); t[f] += num(e[f]); });
    u.costUsd += num(e.costUsd);
    t.costUsd += num(e.costUsd);
    u.eventCount += 1;
    t.eventCount += 1;
    const promptKey = e.promptId || e.eventId;
    if (promptKey && !u._prompts[promptKey]) { u._prompts[promptKey] = true; u.promptCount += 1; }
  }
  const sortKey = function (r) { return [r.hourStart, r.teamId, r.userId || "", r.tool, r.model, r.source].join("|"); };
  const userRows = Object.keys(users).map(function (k) {
    const r = users[k];
    delete r._prompts;
    r.costUsd = round8(r.costUsd);
    return r;
  }).sort(function (a, b) { return sortKey(a) < sortKey(b) ? -1 : 1; });
  const teamRows = Object.keys(teams).map(function (k) {
    teams[k].costUsd = round8(teams[k].costUsd);
    return teams[k];
  }).sort(function (a, b) { return sortKey(a) < sortKey(b) ? -1 : 1; });
  return { userRows: userRows, teamRows: teamRows };
}

// Dirty hours still pending after this run: hours marked since the run started stay.
function remainingDirtyHours(latestDirty, processedHours) {
  const done = {};
  (processedHours || []).forEach(function (h) { done[h] = true; });
  return normalizeHours(latestDirty).filter(function (h) { return !done[h]; });
}
// ---- node: lib/nodes/rollup-finalize-state.js
// Code node "Finalize Rollup State" (rollup.json). Mode: each. Input: "Reload Rollup State".
// Re-reads RollupState just before saving, so dirty hours marked by manual entries
// during this run are kept. Advances lastRunStartedAt only when nothing was truncated.
// Fails the run (no state saved, next run retries) if the hourly replace reported errors.
// Injected constants: REPLACE_NODE ("" when no hours were rebuilt), HOURS_NODE.
// Helpers: workflow-io, graphql, rollup.

const plan = nodeOutput($node, "Plan Rollup Run");
const hoursPlan = nodeOutput($node, HOURS_NODE);
if (REPLACE_NODE) {
  const replaced = $node[REPLACE_NODE] ? $node[REPLACE_NODE].json : null;
  const errors = resultErrors(replaced);
  if (errors.length) throw new Error("rollup_replace_failed: " + JSON.stringify(errors).slice(0, 500));
}
const latest = extractItems($json)[0] || null;
const processed = REPLACE_NODE ? hoursPlan.hours || [] : [];
const input = {
  lastRunFinishedAt: new Date().toISOString(),
  dirtyHours: remainingDirtyHours(latest ? latest.dirtyHours : [], processed)
};
if (!hoursPlan.truncated) input.lastRunStartedAt = plan.runStartedAt;
const field = latest
  ? updateField("state", "RollupState", filterString({ name: ROLLUP_STATE_NAME }), input)
  : insertField("state", "RollupState", Object.assign({ name: ROLLUP_STATE_NAME, lastRunStartedAt: null }, input));
return { stateMutation: buildMutation([field]) };
